cat > /etc/nginx/conf.d/port-6700.conf <<'ANTRIEB_EOF'
server {
    listen 6700 default_server;
    listen [::]:6700 default_server;
    server_name _;

    location = / {
        default_type text/plain;
        return 200 "nginx on port 6700\n";
    }
}
ANTRIEB_EOF
